-- The 30 spells of Nature Magic, the Old Believer's tradition.
-- Rifts World Book 18: Mystic Russia pp.130-135. Batch 1d, and the LAST of the
-- four traditions - with it the book's 131 new spells are all in.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzz-mr-nature-spells.sql
--
-- Read from the book's TEXT LAYER (.cache/books/mystic-russia, page_offset 1)
-- by the same reader that produced the other three batches. Levels run
-- L1:3 L2:4 L3:3 L4:5 L5:2 L6:2 L7:1 L8:3 L9:2 L10:2 L11:2 L12:1 - all twelve, no gaps, unlike Spoiling (no Level Nine) and Living
-- Fire (no Ten or Eleven).
--
-- NO ROW HERE CARRIES `same_spell_as`, AND THAT IS A RESULT RATHER THAN AN
-- OMISSION. Two of the 30 share a name with an existing catalog row and both
-- were put to `scripts/same-spell-lib.mjs`, which rejected both:
--
--   * `Swords to Snakes` - duration 1 vs 2, and the two descriptions share only
--     0.33 of their vocabulary against a floor of 0.35.
--   * `Healing Water` -> `Ocean: Healing Waters` - range 10 vs 3, duration
--     1 vs 2, and one description is 5.4x the length of the other.
--
-- Both were on the survey's withdrawn list of "five spells that disagree on
-- level". WITH THIS BATCH THAT LIST IS FULLY ACCOUNTED FOR, and not one of the
-- five needed a ruling: `Circle of Flame` AGREED with the tradition row it
-- should have been compared against, `Fire Fists` is a real retelling and is
-- linked, and `Fire Ball`, `Swords to Snakes` and `Healing Water` are different
-- spells that happen to share a name. Decision D2 in the survey.
--
-- FOUR COSTS ARE NOT NUMBERS, and none of them is guessed:
--
--   * `Sacred Oath` costs "None" and that is the real price - it is a vow sworn
--     on Moist Mother Earth, not a casting. Stored as 0 and asserted BY NAME
--     below, so a future parse failure that produces a 0 cannot hide here.
--   * `Magic Knots` costs "Varies", and its description prices ten knots
--     individually from 3 to 75. `ppe` holds 3, the minimum, which is what
--     migration 021 says the column is for; the note carries the range.
--   * `Living Bones of Stone` and `Living Bones of Air` print "Self 24;
--     transforming another costs 50" and "Self 28; ... 60". `ppe` takes the
--     figure for the caster themselves.
--
-- `tradition = 'nature'` is its own value. Nature Magic belongs to the Old
-- Believer, and the tradition is what decides which classes may reach it.

INSERT INTO spells
  (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition)
VALUES
  ('Nature: Crunching Egg Shell', 1, 2, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Can be heard up to 12 feet (3.6 m) away per level of the spell caster.', 'One hour per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'Note: Requires real egg shells. The mage sprinkles crushed egg shells on the ground, usually in a circle around him, his bed, campsite, etc., or in front of an entrance way, on a window ledge, in front of a chest or cabinet, and so on. When anybody other than the spell caster steps on the shattered shells it makes an impossibly loud crunch as if magnified by a megaphone or loudspeaker, with every step. Everybody within earshot will hear the noise. A simple safeguard to alert the mage to the presence of intruders. Anybody attempting to prowl is -50%; roll for every two steps.', NULL, 'nature'),
  ('Nature: Melt Bee''s Wax', 1, 2, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Touch', 'Results are immediate; melting ability lasts one melee round per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. The mage can instantly melt hardened bee''s wax held in his hand or bee''s wax in a container that is held in his hand or touched. The melted wax is used as an important ingredient in numerous spells. This spell can also be used to warm honey.', NULL, 'nature'),
  ('Nature: Sacred Oath', 1, 0, 'None', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Self only.', 'Instant', NULL, 'None', NULL, NULL, 'To swear an oath on the sanctity of "Damp (or Moist) Mother Earth" is a solemn vow made before the ancient goddess of the Earth. The Old Believer cannot lie or break his word when he swears on "Moist (or Damp) Mother Earth" or in the name of "Mokosh," another name for Moist Mother Earth. If he does, all his magic powers and spells are reduced by half (half range, half damage, half duration, etc.). Break his oath a second time, and he loses all magical abilities except for his staff and familiar! The halved or lost powers cannot be restored unless the Old Believer begs the goddess of the Earth for forgiveness and a second chance. This requires seven days of fasting from food, 10 hours or more a day of meditation and repentance and, on the morning of the eighth day, mentally transferring, by force of will, 2D6 Hit Points and 2D6 P.P.E. permanently into the Earth - H.P. and P.P.E. are lost forever! If a pine sapling suddenly appears where the mage has focused his energy, he knows he is forgiven and his powers are restored to full (minus those sacrificed to the Earth). If no sapling appears, he must spend the next six months helping others, protecting the Earth from supernatural evil and dark magic, and repeat the process. Note: Mokosh usually forgives. The G.M. can make a random roll if he or she desires; 01-97 means the mage is forgiven and his powers restored. Level Two', NULL, 'nature'),
  ('Nature: Glue with Bee''s Wax', 2, 4, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Touch', 'Results immediate.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. The spell caster can use hot, melted bee''s wax like a powerful adhesive to glue and mend broken items. This "glue" will work on most types of material (paper, plastic, wood, stone, glass, metal, etc.). Equal to a strong, high quality adhesive.', NULL, 'nature'),
  ('Nature: The Bee''s Friend', 2, 4, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Self only.', 'Five minutes per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. This spell makes Honey Bees and all bees regard the mage as a friend so they won''t sting him. It also allows him to crack open their hive without injury to the hive or bees, remove up to two pints of honey or one pound (0.45 kg) of wax, and magically reseal the hive without the bees attacking him.', NULL, 'nature'),
  ('Nature: Make Honey & Syrup Candy', 2, 6, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Touch or up to 10 feet (3 m) away; line of sight.', 'Results are immediate.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. The mage can pour honey or syrup into any basic shape or several small to medium droplets of circles and magically turn them into candy. Up to one pound (1.6 kg) of honey or syrup can be turned into candy per level of experience. The sweet candy is firm but chewable, melts in the mouth, soothes sore throats and tastes delicious.', NULL, 'nature'),
  ('Nature: Sustained by the Earth', 2, 5, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Self only.', 'Results immediate.', NULL, 'Not applicable.', NULL, NULL, 'The spell caster can eat a handful of dirt and gain the sustenance of a complete meal. Unfortunately, it still tastes like dirt. Level Three', NULL, 'nature'),
  ('Nature: Bake Magic Kulich', 3, 7, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.130', 'rifts', 'Touch', 'Immediate results upon eating.', NULL, 'Not applicable.', NULL, NULL, 'A ritual involving the making and baking of "kulich," a Russian sweet bread. Two slices of this bread provides the nourishment and feeling of having eaten an entire meal. One loaf can be made per level of the spell caster. Each loaf can be cut into 20 slices. Note: Requires the ingredients and facilities to make the bread.', NULL, 'nature'),
  ('Nature: Bless Food', 3, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.131', 'rifts', '12 feet (3.6m)', 'Immediate results, that last until the food is eaten.', NULL, 'Not applicable.', NULL, NULL, 'A short prayer or mantra that protects prepared food and drink, or stored food from the "spoiling" magic of witches and the "decay" spell of the Necromancer. Seven pounds (3.2 kg) of food or one gallon of liquids (3.8 liters) can be "blessed" and made impervious to spoiling magic per level of the spell caster. Note: The food is still vulnerable to natural decay and spoiling.', NULL, 'nature'),
  ('Nature: Seal a Wound with Bee''s Wax', 3, 7, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.131', 'rifts', 'Touch', 'Results immediate.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. The Old Believer pours hot bee''s wax over a cut, opened wound or ulcer. The wax does not burn and seals the wound as if it had been sutured closed. The bleeding and pain stop immediately and the injured character heals an extra one Hit Point per 24 hours. When the wound is completely healed (all H.P. restored) the wax falls off, revealing a barely noticeable scar. Level Four', NULL, 'nature'),
  ('Nature: Bee''s Wax Disguise', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.131', 'rifts', 'Touch', 'Five minutes per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. The spell caster can use hot wax on his own face or body, or on a willing participant, and mold it into a disguise. The hot wax does not burn as it is applied, in fact it feels soothing, and can be built up, sculpted and molded like makeup putty. Being hot wax, hair and even fur is easily applied to the skin, as are horns and other cosmetic features. After the desired features are is finished, the spell caster says one final phrase and the wax features transform to look like real, flexible flesh, bone and hair. The false face will remain in place as a real looking disguise until the spell elapses or the character is blasted by M.D. or magical heat. Magic fire will melt the disguise. The quality of the disguise is equal to the Disguise Skill at 62% +2% per level of the spell caster.', NULL, 'nature'),
  ('Nature: Colored Egg', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.131', 'rifts', 'Touch', 'Immediate results upon eating.', NULL, 'Not applicable.', NULL, NULL, 'A ritual involving the making of a hard-boiled egg that is then dyed one or more different colors, like an Easter Egg. Eating the egg quells hunger for 24 hours and provides the nourishment and sustenance of three daily meals (breakfast, lunch and dinner). One colored egg can be made per level of the spell caster. The entire egg (minus the shell) must be eaten for the magic to work. Note: Requires the ingredients and facilities to make the egg; i.e. fresh chicken or duck eggs, boiling water and food dye. The egg will remain fresh and edible for one week per level of the spell caster and is impervious to Spoiling Magic.', NULL, 'nature'),
  ('Nature: Hold Tight with Bee''s Wax', 4, 5, '5 for preserving purposes, 10 to seal a window, door or large container like a crate or trunk.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.131', 'rifts', 'Touch', 'Results are immediate, duration varies.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. The Old Believer can pour hot bee''s wax around the edges of the lid or cover to any container (jar, bottle, barrel, etc.) to seal it airtight. This magic is typically used to preserve canned and bottled food and drinks, increasing the life of the preserved food, drink or specimen 10 times longer than usual (years). 10 small containers (each holding no more than one gallon or 7 pounds/3.2 kg of material) can be sealed tight per level of the mage''s experience. They can be opened by either warming the wax seal or with a P.S. of 15. A magical bee''s wax seal can also be applied to windows, doors, and large containers such as trunks and coffins to hold them tight. This magic is used to momentarily keep the lid shut, or window or door closed in an effort to keep people in or out. To break the bee''s wax seal and open the item, a character needs a combined P.S. of 40 or supernatural P.S. of 20 or higher! The magic lasts for 20 minutes per level of the spell caster. Once the spell duration elapses, a P.S. of 12 can force it open. Note that the Old Believer who cast the spell can open the wax sealed door (or whatever) normally, as if the wax wasn''t there. Other mages with the same power can open it with a P.S. of 15 or by melting the wax by running their finger over it and casting the Melt Wax spell (counts as four melee actions).', NULL, 'nature'),
  ('Nature: Make Honey Medicine', 4, 8, '8 or 12', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.131', 'rifts', 'Touch or can cast the magic on a piece of honey candy or spoonful of honey up to 20 feet (6 m) away; line of sight.', 'Results are immediate.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. The mage can turn a spoonful of honey into a magical elixir that, when taken orally, straight or poured into hot tea or other drink, will instantly soothe a sore throat and stop coughing for 2D4 hours. It can also Cure Minor Disorders as quickly as the .common wizard spell of the same name (see Rifts RPG, page 172) - basically cures non-magical hiccups, indigestion, gas, heartburn, minor nausea, motion sickness, slight headaches, minor muscle aches and low fever. P.P.E. cost is 8 points. The Honey Medicine can also be poured and rubbed on the skin to stop the itch, irritation and pain of a rash or burn. P.P.E. cost is still 8 points. To stop/negate poison, a somewhat more potent Honey Medicine must be enchanted, requiring 12 P.P.E. This medicine immediately stops the illness and penalties caused by poison and restores 1D6 Hit Points. Note: This magical "medicine" has no effect on magic illness, curses or potions.', NULL, 'nature'),
  ('Nature: Negate Spoiling Magic', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.132', 'rifts', 'By touch or 10 feet (3 m) away; line of sight.', 'Immediate effect.', NULL, 'Not applicable.', NULL, NULL, 'The sorcerer can negate the damage and danger created by Spoiling Magic, restoring one pound (0.45 kg) of food or a pint of liquid per level of experience. Level Five Glimpse of the Future', NULL, 'nature'),
  ('Nature: A Wood & Water Divination', 5, 15, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.132', 'rifts', 'On behalf of another person, family or a community.', 'Immediate results.', NULL, 'Not applicable; unwilling recipients are immune.', NULL, NULL, 'After participating in a cheerful, circle dance, throwing a garland made from a birch tree into a river imparts some tiny measure of divination. If thrown in by a girl/young woman and it floats, it means she will be wed within the next two years and that her prospective fiance can be found in the direction the garland floated away (the magic can defy the natural current of the water). If the garland sinks, the girl can expect tragedy to befall her or her family, perhaps even her own death. When performed by the Old Believer on behalf of a community or family, floating with the current means prosperity in the coming year. Floating in a spinning motion means things are good and safe now, but there are forces afoot that may change this. Sinking means tragedy (disease, crop failure, fire, a grievous loss, etc.) or that dark forces lurk in its future. Unfortunately, exactly what this tragedy might be is not indicated. If the garland bursts into flame the moment it hits the water, it indicates the presence of great supernatural or magical evil (typically a high-powered practitioner of magic, terrible monster, greater demon or demon horde). For a few minutes the flaming garland will bob and move in the general direction where the evil lives or will come from, then sinks, indicating danger and possible tragedy.', NULL, 'nature'),
  ('Nature: Rope of Steel', 5, 12, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.132', 'rifts', 'Touch or from 10 feet (3 m) away per level of the spell caster.', '15 minutes per level of the spell caster.', NULL, 'Not applicable', NULL, NULL, 'This spell turns ordinary S.D.C. hemp cord, horse hair rope, or any rope made of natural fibers into a Mega-Damage steel. It retains the feel, weight and flexibility of ordinary rope, but has a tensile strength of two tons and it takes 12 M.D. to cut it! Prisoners bound with the enchanted rope require a combined supernatural P.S. of 50 of higher to break it or pull free (-30% penalty to Escape Artist skill). Note: This spell does not work on string, yarn, thread, rags, wire, chain, metal or plastic. Also see Magic Knots. Affects up to 50 feet (15.2m) of rope per level of the caster. Level Six', NULL, 'nature'),
  ('Nature: Magic Knots', 6, 3, 'Varies', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.132', 'rifts', 'Touch. The mage must make the knot(s) while casting the spell.', 'Results are immediate. Duration of the knot varies.', NULL, '-2', NULL, NULL, 'The spell caster can make one or more magic knots. Each type of knot has a special meaning and magic. Fake Knot: A knot that looks tight and strong, but which is easily worked loose in one melee round (15 seconds). P.P.E.: 4 Four Winds Knot: When combined with this magic, ordinary rope, leather strips, wire or chains will hold ethereal spirits, including the Midnight demon, entities, ghosts and vampires (they can not turn into mist when bound by this magic knot). P.P.E.: 20. Duration: Five minutes per level of the spell caster. Hangman''s Knot/Noose/Choker: A sliding knot that tightens from being pulled, weight and tension. A simple nonmagical use is hanging criminals or restraining animals or prisoners (tightens and chokes the person or animal that pulls on the rope). When enchanted, the Hangman''s Noose can be used to hang Mega-Damage Creatures! P.P.E.: 50; Duration: Three minutes per level of the spell caster. When worn around the neck as a cord or necklace that ends in a small, symbolic hangman''s noose, the character is +2 to save vs disease and the effects of Spoiling Magic and spoiled foods. P.P.E.: 60; Duration: 24 hours per level of the spell caster (can be made a permanent protective charm with the expenditure of 230 P.P.E.). It can also be used to tie charms and jewelry. When used to tie a cluster of 1D4+1 tiny bones, or a little pouch of bones to a cord or chain worn around the neck, it protects the wearer from all Death Curses and magic that does damage direct to Hit Points; +6 to save. Even if the save fails, damage and penalties are half. P.P.E.: 75; Duration: 12 hours per level of the spell caster, but can be made a permanent protective charm with the expenditure of 330 P.P.E. Knotted Skull: If worn, the skull is likely to be that of a small animal tied to string and held by 2-3 knots. This serves as a charm that protects any food carried by the character from Necromantic Decay or Maggots spells, and is +2 to save vs Magic Spoiling. P.P.E.: 45; Duration: 12 hours per level of the spell caster, but can be made a permanent protective charm with the expenditure of 300 P.P.E. If a skull is hung from a tree, post or pole in the four comers of the wind (north, south, east, west) in a crop field, it brings good fortune and reduces damage from disease, frost and vermin by 15%. Moreover, the area is impervious to spoiling unless two of the skulls are cut down and smashed. An easy thing to accomplish, but a clear indication of foul intent and the possible presence of black magic and probably a witch or demon. P.P.E.: - 80; Duration: 24 hours per level of the spell caster, but can be made a permanent protective charm with the expenditure of 290 P.P.E. Sheepshank Knot: When combined with this enchantment the knot can strengthen rope and hold or pull two times the weight the rope can normally accommodate. P.P.E.: 6; Duration: One hour per level of the spell caster. Simple Knot: When enchanted, the knot is strong, reliable and will not come undone unless untied or cut. P.P.E.: 3; Duration: Until untied. Slip Knot: This enchantment is used to bind two pieces of rope together. Once the knot is finished, it can be slipped or pulled to the end of the rope and right off, making the two pieces one strong, single, unknotted piece of rope! P.P.E.: 7; Duration: Permanent results. Half Hitch Knot: When combined with this enchantment, any boat tied to a dock will not slip loose unless somebody undoes the knot. P.P.E.: 6; Duration: Until untied.', NULL, 'nature'),
  ('Nature: Strength of the Earth', 6, 12, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.133', 'rifts', 'Self only.', 'Two minutes per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'The expenditure of P.P.E. and eating a pinch of earth temporarily turns the character''s P.S. into supernatural strength and his natural S.D.C. (not H.P.) into M.D.C. In addition, fire and cold based magic inflicts half damage. Note: The punches and kicks from supernatural P.S. inflict M.D. and the character can lift and carry weight lOOx his P.S. Level Seven', NULL, 'nature'),
  ('Nature: Living Bones of Stone', 7, 24, 'Self 24; transforming another costs 50.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.133', 'rifts', 'Self or another character by touch.', 'Five minutes per level of the spell caster.', NULL, 'Not applicable; unwilling recipients are immune.', NULL, NULL, 'This is not a literal transformation, but a magical enchantment that makes the bones roughly as strong as stone and the body a Mega-Damage Structure with 6D6x2 M.D.C. +3 points per level of experience. Also double the character''s weight. Bones are virtually impossible to break (requires a supernatural P.S. of 55 or greater or a fall from more than 500 feet/153 m).Falls under 500 feet (152 m) do no damage, those from higher up only inflict 1D6 M.D. per every 1000 feet (305 m), and the enchanted character''s punches and kicks inflict 1D6 M.D. Explosions, and cold and fire based magic do only half damage, but energy blasts and magic weapons do full damage. If M.D.C. is reduced to three points or less, the spell is broken and the character is exhausted, weak and injured, his S.D.C. reduced to zero and Hit Points down to 3D4. The spell cannot be repeated for at least one hour and until at least 75% of the character''s Hit Points are restored. Note: This magic only affects the body of the character, and not anything he may be wearing. The transformed character can will himself back to normal at any time; counts as one melee action. Level Eight', NULL, 'nature'),
  ('Nature: Living Bones of Air', 8, 28, 'Self 28; transforming another costs 60.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.133', 'rifts', 'Self or another character by touch.', 'Five minutes per level of the spell caster.', NULL, 'Not applicable; unwilling recipients are immune.', NULL, NULL, 'This is not a literal transformation, but a magical enchantment that makes the body, and any clothes or possessions on it at the time of the invocation, as light as a feather and temporarily insubstantial, becoming semi-transparent like a ghost. In this form, the character can walk and run at three times his normal speed, walk or run across water, leap into the air and float 10 feet (3 m) high or across per level of the spell caster, and is impervious to heat, cold, and all physical attacks! Only psionic attacks and magic that affects the mind or emotions (including illusions) can hurt the transformed character. Unfortunately, spell casting is impossible in this form because speaking or making any sound is impossible. Moreover, the intangible character can not touch, carry, operate or strike anything in the physical world except via psionic powers (if any). Despite being intangible, the ghostly figure cannot walk through solid walls and objects. However, he can squeeze through narrow openings like a partially open window and bars that are at least two inches apart. Note: The transformed character can will himself back to normal at any time; counts as one melee action.', NULL, 'nature'),
  ('Nature: Demon''s Mock Funeral', 8, 40, '40 for one individual, +20 for each additional member of a group or family included in the funeral as dead.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.133', 'rifts', 'Self or other.', 'Immediate Results; 24 hours +12 per level of the spell caster.', NULL, 'Standard save vs illusion with a penalty of -8; any bonuses to save vs illusion do not apply to this ritual. Note: Only effective against the select supernatural beings.', NULL, NULL, 'An unusual and strange magical ritual that creates a convincing illusion designed to trick supernatural beings (good and evil), Russian Woodland Spirits, Faerie Folk, Witches (all types) and then- willing minions into believing a particular person is dead. This is usually done to stop the creature from following, troubling or seeking revenge upon the individual portrayed as dead. It can also be used to lower the creature''s guard concerning old enemies or famed heroes (i.e. thinking his enemy or opponent is dead, the creature comes out in the open and reestablishes its operations/activity without worrying about interference or attack from the deceased). Interestingly, this illusion only affects those beings noted previously, anybody else looking into the coffin sees the obviously artificial effigy. Consequently, any (fake) mourners and visitors paying their respects should wail and mourn to keep the illusion convincing. However, all Russian peasants (including children), Reavers, Gypsies and Russian people in general, recognize and understand exactly what this mock funeral is all about and act accordingly - kneeling or bowing, and crossing themselves as they pass the coffin, placing a flower on the coffin, weeping, etc. Note: Any mortal removing the effigy from the coffin breaks the spell; supernatural beings and all those listed earlier won''t touch the body.', NULL, 'nature'),
  ('Nature: Swords to Snakes', 8, 25, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.134', 'rifts', '60 feet (18.3m)', 'One melee round (15 seconds) per level of the spell caster.', 'None, other than temporarily disarming one''s foe.', 'None, however, magic weapons are immune to this magic.', NULL, NULL, 'This powerful magic spell temporarily turns knives and swords (including Vibro-knives and swords, but not other types of weapons) into seemingly ordinary, nonpoisonous snakes! They don''t do anything but squirm and deprive a warrior of his weapon. One sword/dagger can be transformed per level of the spell caster. Level Nine', NULL, 'nature'),
  ('Nature: Enchant The Mighty Rooster', 9, 45, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.134', 'rifts', 'Touch or 10 feet (18.3 m); line of sight.', 'One melee round (15 seconds) per level of the spell caster.', 'None', 'Not applicable. Undead must save vs H.F.', NULL, NULL, 'The Rooster is a traditional Harbinger of the New Day and announces the dawn and rising of the morning sun, thus it is an enemy of creatures of darkness. When in the hand of the Old Believer and enchanted by his magic, the Rooster becomes a weapon against vampires and the Unclean. While enchanted, the bird can be used to identify vampires, Dybbuk, or any undead, as well as metamorphed Unclean, by crowing, clawing and pecking at the hell-spawned creatures whenever within 20 feet (4.6 m) of one. Furthermore, the crow of the rooster hurts the ears of the undead and Unclean and strikes fear into the black hearts of these fiends equal to a Horror Factor of 16. A failed roll means the creature loses one melee action for that round and is -1 on initiative and -1 to parry and dodge, namely because the demons are so frightened and unnerved by its crowing. The penalties last for one minute, but if the rooster continues crowing every 30-60 seconds (and the animal will as long as these creatures are nearby) the penalties remain in place until the bird stops making noise. Note: If the vampires or Unclean know that dawn will be approaching soon (within the next 1-30 minutes) the penalty is doubled and a failed H.F. roll means the demon flees from the approaching light of day, even though it may be 30 minutes away. The enchanted rooster can also track such creatures like a bloodhound to their current location, lair, or hiding place. Tracking skill is 79% +1% per level of the spell caster.', NULL, 'nature'),
  ('Nature: Magic Egg', 9, 70, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.134', 'rifts', 'By touch.', 'The duration of the magic released varies.', NULL, 'Varies, if it applies at all.', NULL, NULL, 'A large egg that has had its yolk removed through a tiny hole and the shell colorfully decorated with paint and bits of glued sparkles or seashells, bone and tiny gems and/or feathers. This enchantment rums the egg shell into a magic container with one M.D.C. To release the magic inside, one simply cracks the egg open. The magic inside the egg always affects the person who opens it, and may contain any of the following: - 1D4+1 Honey Bees per level of the spell caster are released. If the opener is of a good alignment (including unprincipled), they will circle the character''s head for a moment. If he is injured, each bee will land on him and sting (a symbolic gesture so the magic will work through body armor). Each sting restores one Hit Point (or M.D.C. if a Mega-Damage creature). If healthy, the bees vanish, but in so doing, leave the character with a psychic premonition about some event in the immediate future, or about a friend or loved one in danger (i.e. that the person is in danger, the desperateness of the situation, and his general whereabouts). Duration: Approx. 1D4 melee rounds. The bees attack any evil creature and, at least momentarily frighten and obscure vision until they can be killed. The individual plagued by the bees is -2 on initiative, -1 on all combat maneuvers and -15% to perform any skill. Furthermore, he is very conspicuous because of the swarm of buzzing bees around his head, making prowl and any stealthy action (pick pocket, seduction, etc.) impossible. Those seeing the strange occurrence are frightened or startled (H.F. 12) and likely to move out of his way. The bees are ordinary and can be killed from 1D4 S.D.C. points of damage, however, they are small and fast so attacks (other than fumigation) are -5 to strike per each bee. Duration: The bees swarm around the head of the evil individual for five minutes per level of the spell caster. - An egg-shaped sphere of mystic energy; 10 P.P.E. points per level of the spell caster. This energy can be used within the next minute (four melee rounds) in the performance of magic, but only by the character who cracked open the egg. - Armor of Ithan or Living Bones of Stone is cast upon the opener of the egg. Equal to the level of the spell caster. - Calm Storm is cast equal to the level of the spell caster. Speed of the Snail (50 P.P.E.) Identical to the spell found on page 183 of Rifts. Level Ten', NULL, 'nature'),
  ('Nature: Healing Water', 10, 50, '50 for healing pool, 200 to restore life.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.134', 'rifts', '10 feet or by touch.', 'One minute per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'The mage can temporarily transform a tub, barrel of water or pond into "healing waters." Anybody placed in the water while it is enchanted will be physically restored. This means broken bones are magically knitted back together, cuts and bruises healed, and internal bleeding stopped and repaired; 4D6 Hit Points (no S.D.C.) are restored. As many as five people per minute can be healed; must immerse themselves completely for 6-10 seconds each. If 200 P.P.E. is spent, and one pint of the spell caster''s own blood added to the water, it can restore the life of the dead, provided that the body of the deceased is whole and has not been dead for more than three hours. As many as one character can be brought back to life (2D6 H.P. above zero) per minute. Note: The mage is temporarily drained as part of his life force is used to supplement and revive the deceased; reduce the spell caster''s Hit Points, S.D.C., speed, all bonuses, and the number of attacks per melee round by half for 24 hours.', NULL, 'nature'),
  ('Nature: Snakes to Swords', 10, 25, '25 for small nonpoisonous snakes, 50 for non-lethal venomous snakes, 100 for lethal snakes and constrictors, and 140 for select Worms of Taut.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.135', 'rifts', 'Touch and hand to hand combat range.', 'One minute per level of experience.', 'Varies with snake type.', '18 or higher for normal snakes and 14 or higher for Worms of Taut. Victims of magic venom need to roll a 14 or higher to save vs magical poison.', NULL, NULL, 'Note: By Mark Sumimoto with Kevin Siembieda. This magic amplifies and combines with the snake''s essence to reshape the serpent into a magic blade. The design of the weapon varies with the serpent being used. The handle or hilt retains the same color or color pattern as the snake and has the feel of snake skin (or worm skin as the case may be). The blade is silver and engraved with a design that looks like the serpent it was created from. The damage and size of the blade also varies with the type of snake being used. - Nonpoisonous snakes become daggers or short swords that inflict 3D6 H.P./S.D.C. or one M.D., depending on the nature of the target (meaning H.P./S.D.C. creatures take S.D.C. damage, while Mega-Damage creatures suffer M.D.). - Constrictors (nonpoisonous), like pythons or boas, become large swords, that inflict 5D6 S.D.C. or 1D6 M.D. - Snakes with nonlethal venom become broad swords or other large swords that inflict 6D6 H.P./S.D.C. or 2D6 M.D. depending on the nature of their opponent. - Lethal venomous snakes (i.e snakes who often kill with a single bite, including most vipers) become large swords that inflict !D4xlO S.D.C. or 3D6 M.D., plus the victim struck by the weapon must roll to save vs poison (14 or higher). A failed roll means an additional 2D6 damage (S.D.C. or M.D.) plus the victim suffers from a burning sensation and light-headedness (-10% on all skills for 24 hours). - Small Worms of Taut can also be transformed by this magic. Fire Worms are turned into flaming swords that inflict 1D4><10+8 M.D. (sorry, M.D. only). Nippers become large'' swords that inflict 3D6 M.D. (sorry, M.D. only), plus the victim struck by the weapon must roll to save vs poison (14 or higher). A failed roll means double damage (and -10% on all skills for 24 hours)! Tomb Worms become daggers or short swords that inflict 2D6 M.D. (sorry, M.D. only). Note: Shifters or other mages who have snakes or Worms of Taut as then- familiars will find this spell to be particularly useful. They will also be able to cast this spell at the standard P.P.E. cost, instead of the doubled cost required for those who do not practice necromancy. Level Eleven', NULL, 'nature'),
  ('Nature: Circle Dance', 11, 200, '200, but note that 10 P.P.E. can be drawn from each participant without their noticing or caring because they are all willing participants in the ritual.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.135', 'rifts', 'Varies, but no more than a five mile (8 km) diameter.', 'Results are immediate and last for 12 hours per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'The "khorovody," or circle dance, is a ritual magic disguised as a cheerful and festive event that involves singing and nurtures laughter, fun and good feelings in the participants (a few to over a hundred) and all observers, which can number over a thousand. This happy and positive feeling combined with the magic makes everybody who participates, watches or listens confident, positive and cheerful. It also makes them all +2 to save vs all magic with evil intent for the next 24 hours +4 hours per level of the spell caster. Furthermore, the detestable merriment sends lesser demons, evil Woodland Spirits, Faerie Folk, witches and evil beings retreating to sulk and grumble in their dark and dingy lairs for the next 48 hours (coming out only if drawn out).', NULL, 'nature'),
  ('Nature: Protective Magic Ring', 11, 140, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.135', 'rifts', 'Varies with the current need, maximum of one mile (1.6 km) diameter per level of experience.', 'Results are immediate and last for 12 hours per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'This ritual magic can be used in one of two ways: Circling a farm or homestead before sunrise and either sweeping around the area three times in a circle with a newly made (not yet used) broom, or by encircling the place and laying small charms and icons along the path of the circle to: 1) prevent illness, lesser demons, and evil Woodland Spirits from penetrating the protective magic circle for the next 24 hours +1 hour per level of the spell caster; or 2) to send lesser demons and evil Woodland Spirits and Faeire Folk running from inside the enchanted circle and stay gone for 8 hours per level of the spell caster. Summon Fog (140 P.P.E.) Identical to the spell found on page 186 of Rifts. Level Twelve', NULL, 'nature'),
  ('Nature: Bee''s Wax Effigy', 12, 280, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.135', 'rifts', 'Touch to make the effigy, but the effects of its magic are good up to five miles (8 km) away.', 'Results are immediate and last for 12 hours per level of the spell caster. Takes 20 minutes to make the figure and perform the magic.', NULL, 'Not applicable.', NULL, NULL, 'Note: Ancient and rare Beekeeper''s Magic. A ritual magic that involves the mage making a small wax figure out of bee''s wax and applying to it a lock of hair or fingernails of the character to be protected. The wax figure is then put in a safe (often secret) place. Once the ritual is completed, the magic is in place. The Bee''s Wax Effigy is a form of protection magic that endows the person it represents with one of the following: - Impervious to fire, including M.D. plasma and magic fire. - Impervious to cold, including magic cold and ice shards (harmlessly bounce off the character although they sting a bit). - Impervious to poison and disease, including magical illness, spoiling and toxins (like the poison pimples of the Kaluga Hag), but not curses. - Impervious to mind control and possession. - Resistant to Witches - +3 to save vs all spells, curses, spoiling and psionic attacks from any type of witch. - The Blessing of the Good Earth - this protection comes in the way of increased strength and endurance making the recipient +6 to P.S., immune to fatigue, and +1 to save vs magic, poison, and disease. Calm Storms (200 P.P.E.) Identical to the spell found on page 186 of Rifts. Summon Rain (200 P.P.E.) Identical to the spell found on page 187 of Rifts.', NULL, 'nature');

-- Read the result back. Each batch asserts its OWN rows and nothing else: a
-- cross-batch assertion is an assertion about execution order in disguise, and
-- data scripts run in filename order rather than in batch order.
SELECT 'nature spells inserted' AS assertion, count(*) AS got, 30 AS want
  FROM spells WHERE tradition = 'nature';

SELECT 'every one is prefixed' AS assertion, count(*) AS got, 30 AS want
  FROM spells WHERE tradition = 'nature' AND name LIKE 'Nature: %';

SELECT 'every one cites this book by page' AS assertion, count(*) AS got, 30 AS want
  FROM spells WHERE tradition = 'nature' AND source_book LIKE 'Rifts World Book 18: Mystic Russia p.%';

SELECT 'every one carries a cost' AS assertion, count(*) AS got, 29 AS want
  FROM spells WHERE tradition = 'nature' AND ppe > 0;

-- A spell the book prints as costing NOTHING is not a parse failure, and is
-- asserted by name so it cannot be one silently.
SELECT 'and the free ones are free on purpose' AS assertion, count(*) AS got, 1 AS want
  FROM spells WHERE tradition = 'nature' AND ppe = 0
   AND name IN ('Nature: Sacred Oath');


SELECT 'every one carries a description' AS assertion, count(*) AS got, 30 AS want
  FROM spells WHERE tradition = 'nature' AND length(description) > 40;

SELECT 'the schedules carry their note' AS assertion, count(*) AS got, 10 AS want
  FROM spells WHERE tradition = 'nature' AND ppe_note IS NOT NULL;

SELECT 'the retellings are linked' AS assertion, count(*) AS got, 0 AS want
  FROM spells WHERE tradition = 'nature' AND same_spell_as IS NOT NULL;

SELECT 'and every link resolves to a real row' AS assertion, count(*) AS got, 0 AS want
  FROM spells r WHERE r.tradition = 'nature' AND r.same_spell_as IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM spells t WHERE t.name = r.same_spell_as);

SELECT 'no row outside this book was written' AS assertion, count(*) AS got, 0 AS want
  FROM spells WHERE tradition = 'nature' AND source <> 'import';

